                                <div><label className="text-xs font-bold text-gray-500 block mb-1">پیشرفت پروژه (%)</label><input type="number" className="w-full border rounded-lg p-2 text-sm" value={projectForm.progress} onChange={e => setProjectForm({...projectForm, progress: Number(e.target.value)})} /></div>
                            </div>
                            <button onClick={handleSaveProject} className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-all">{t.saveProject}</button>
                        </div>
