                <div className="p-4 border-t border-gray-100 bg-white shrink-0 flex justify-end"><button onClick={() => setSelectedTicketId(null)} className="px-6 py-2 bg-gray-100 text-gray-700 hover:bg-gray-200 rounded-xl font-bold transition-colors">بستن</button></div>
            </div>
        </div>
    );
  };

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {showInvoiceModal && selectedTicket && (
          <InvoiceModal customer={{ id: selectedTicket.customerName, fullName: selectedTicket.customerName, companyName: selectedTicket.companyName, location: selectedTicket.location, phoneNumber: selectedTicket.phoneNumber, whatsappNumber: selectedTicket.whatsappNumber, firstContact: '', totalTickets: 0 }} template={config.invoiceTemplate || { companyName: config.appTitle, address: '', phone: '', footerText: '', termsConditions: '', defaultTaxRate: 0, colorTheme: '#4f46e5' }} initialData={editingInvoice} onSave={(inv) => { const updatedProjectData = { ...projectForm, invoices: [...(projectForm.invoices || []), inv], isActive: true }; onUpdateTicket(selectedTicket.id, { projectData: updatedProjectData }, currentUser.fullName, `Invoice ${inv.number} issued.`); setShowInvoiceModal(false); }} onClose={() => setShowInvoiceModal(false)} />
      )}
      {showNewProjectModal && (
