                <button onClick={() => setActiveTab('forms')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'forms' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconClipboard className="w-5 h-5" /><span className="font-medium">{t.forms}</span></button>
                <button onClick={() => setActiveTab('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'sales' ? 'bg-green-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconMoney className="w-5 h-5" /><span className="font-medium">{t.sales}</span></button>
                {(isAdmin || isMaster) && (<button onClick={() => setActiveTab('financial')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'financial' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconChart className="w-5 h-5" /><span className="font-medium">{t.financial}</span></button>)}
                {hasCustomerAccess && (<button onClick={() => setActiveTab('customers')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'customers' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconUsers className="w-5 h-5" /><span className="font-medium">{t.customers}</span></button>)}
                {isAdmin && (<button onClick={() => setActiveTab('personnel')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconShield className="w-5 h-5" /><span className="font-medium">{t.personnel}</span></button>)}
                {isAdmin && (<button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}><IconSettings className="w-5 h-5" /><span className="font-medium">{t.settings}</span></button>)}
            </div>
            <button onClick={onLogout} className="w-full text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 py-3 rounded-xl transition-colors mt-6">{t.logout}</button>
        </div>
      </div>

      <div className="flex-grow">
        {activeTab === 'staff_reports' && <ReportManager currentUser={currentUser} personnel={personnel} lang={lang} config={config} />}
        {activeTab === 'goals' && <GoalTracker currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                 <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.myTasks}</div><div className="text-2xl font-black text-indigo-600">{tasks.filter(tk => tk.assigneeIds.includes(currentUser.id) && !tk.isCompleted).length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.allRequests}</div><div className="text-2xl font-black text-gray-800">{tickets.filter(t => t.status !== 'تکمیل شده' && t.status !== 'لغو شده').length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.activeProjects}</div><div className="text-2xl font-black text-purple-600">{tickets.filter(t => t.projectData?.isActive).length}</div></div>
                     <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm"><div className="text-gray-500 text-xs mb-1">{t.newMessages}</div><div className="text-2xl font-black text-blue-600">{unreadMessagesCount}</div></div>
                 </div>
                 <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                     <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-4">
                         <div className="flex gap-2">
                             <div className="flex bg-gray-100 p-1 rounded-lg">
                                 {canViewAllTickets && <button onClick={() => setFilterMode('all')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'all' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.allCompany}</button>}
                                 <button onClick={() => setFilterMode('my')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${filterMode === 'my' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>{t.myCartable}</button>
                             </div>
                             <select className="bg-gray-100 text-gray-600 text-sm font-bold px-3 py-1.5 rounded-lg border-transparent focus:border-gray-300 outline-none" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}><option value="all">{t.allStatuses}</option>{Object.values(TicketStatus).map(s => <option key={s} value={s}>{s}</option>)}</select>
                         </div>
                     </div>
                     <div className="overflow-x-auto"><table className="w-full text-start"><thead className="bg-gray-50 text-gray-500 text-sm"><tr><th className="px-4 py-3 w-12">{t.row}</th><th className="px-4 py-3">{t.code}</th><th className="px-4 py-3">{t.service}</th><th className="px-4 py-3">{t.status}</th><th className="px-4 py-3 text-center">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{paginatedTickets.map((ticket, idx) => (
                        <tr key={ticket.id} className="hover:bg-gray-50">
                            <td className="px-4 py-3 text-center text-xs text-gray-400">{(currentPage - 1) * ITEMS_PER_PAGE + idx + 1}</td>
                            <td className="px-4 py-3"><div><span className="font-mono text-[10px] text-gray-400 block">{ticket.id}</span><span className="font-bold text-gray-800 text-sm">{ticket.customerName}</span></div></td>
                            <td className="px-4 py-3"><div className="text-sm font-medium text-gray-700">{getServiceTitle(ticket.serviceId)}</div></td>
                            <td className="px-4 py-3"><span className={`px-2 py-1 rounded text-[10px] font-bold ${getStatusBadge(ticket.status)}`}>{ticket.status}</span></td>
                            <td className="px-4 py-3 text-center"><button onClick={() => setSelectedTicketId(ticket.id)} className="bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-colors">{t.check}</button></td>
                        </tr>
                     ))}</tbody></table></div>
                 </div>
            </div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialDashboard()}
        {activeTab === 'sales' && <SalesDashboard currentUser={currentUser} personnel={personnel} services={services} onUpdatePersonnel={onUpdatePersonnel} onUpdateServices={onUpdateServices} lang={lang} />}
        {activeTab === 'projects' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex justify-between items-center"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><div className="bg-purple-100 text-purple-600 p-2 rounded-lg"><IconProject className="w-6 h-6" /></div>{t.activeProjects}</h2></div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">{activeProjects.map(project => (<div key={project.id} className="bg-white rounded-2xl border border-gray-200 p-5 shadow-sm hover:shadow-lg transition-all cursor-pointer group relative overflow-hidden" onClick={() => setSelectedTicketId(project.id)}><div className="absolute top-0 left-0 w-1 h-full bg-purple-500"></div><div className="flex justify-between items-start mb-3"><span className="text-xs font-bold text-gray-400">#{project.id}</span><span className={`text-[10px] px-2 py-0.5 rounded border ${getStatusBadge(project.status)}`}>{project.status}</span></div><h3 className="font-bold text-gray-900 mb-1">{project.customerName}</h3><p className="text-xs text-gray-500 mb-4">{getServiceTitle(project.serviceId)}</p><div className="mb-4"><div className="flex justify-between text-xs text-gray-500 mb-1"><span>{t.progress}</span><span className="font-bold text-purple-600">{project.projectData?.progress}%</span></div><div className="w-full bg-gray-100 rounded-full h-1.5"><div className="bg-purple-500 h-1.5 rounded-full transition-all" style={{ width: `${project.projectData?.progress}%` }}></div></div></div><div className="flex items-center justify-between text-xs text-gray-400"><span>{new Date(project.createdAt).toLocaleDateString()}</span><span className="group-hover:text-purple-600 font-bold transition-colors">{t.view} →</span></div></div>))}</div>
            </div>
        )}
        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'customers' && hasCustomerAccess && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && hasTariffAccess && <ServiceManager services={services} onUpdate={onUpdateServices} readonly={!isAdmin && !isMaster} lang={lang} />}
        {activeTab === 'personnel' && isAdmin && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'settings' && isAdmin && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={isMaster} />}
        {activeTab === 'forms' && (
            <div className="space-y-6">
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><div className="bg-indigo-100 text-indigo-600 p-2 rounded-lg"><IconClipboard className="w-6 h-6" /></div>{t.formsTitle}</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">{customForms.map(form => (<div key={form.id} className="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm hover:shadow-md cursor-pointer transition-all" onClick={() => setSelectedCustomForm(form)}><h3 className="font-bold text-gray-900">{form.title}</h3><p className="text-xs text-gray-500 mt-1">{form.category}</p><div className="mt-4 pt-4 border-t text-xs text-gray-400">{form.fields.length} فیلد</div></div>))}</div>
            </div>
        )}
        {activeTab === 'staff_reports' && <ReportManager currentUser={currentUser} personnel={personnel} lang={lang} config={config} />}
      </div>
      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Ticket, TicketStatus, ServiceOption, Personnel, Customer, AppConfig, ProjectDetails, AttachedFile, Currency, Payment, InternalMessage, Invoice, Task, Meeting, SystemLog, ProjectMilestone, ProjectRisk, ProjectTeamMember, KPI, CustomForm, PerformanceReport, SalesRecord } from '../types';
import { IconCheck, IconActivity, IconUsers, IconBriefcase, IconLayout, IconPaperclip, IconShield, IconSettings, IconClock, IconFile, IconEdit, IconTrash, IconProject, IconMoney, IconUpload, IconPlus, IconChart, IconMail, IconInvoice, IconList, IconCalendarClock, IconHistory, IconCopy, IconSearch, IconFlag, IconAlertTriangle, IconTime, IconTrendingUp, IconRefreshCw, IconLock, IconMegaphone, IconBarChart2, IconMapPin, IconWhatsapp, IconTarget, IconClipboard, IconFolder, IconAward, IconWallet } from './Icons';
import { ServiceManager } from './ServiceManager';
import { PersonnelManager } from './PersonnelManager';
import { CustomerManager } from './CustomerManager';
import { SettingsManager } from './SettingsManager';
import { InternalMessenger } from './InternalMessenger';
import { InvoiceModal } from './InvoiceModal';
import { TaskManager } from './TaskManager';
import { MeetingCalendar } from './MeetingCalendar';
import { PerformanceReports } from './PerformanceReports';
import { KPIManager } from './KPIManager';
import { SalesDashboard } from './SalesDashboard';
import { ReportManager } from './ReportManager';
import { GoalTracker } from './GoalTracker';
import { uploadFileWithProgress, logSystemAction, subscribeToSystemLogs, saveTaskToCloud, restoreEntityFromLog, sendInternalMessage, subscribeToCustomForms, saveReport, subscribeToSalesRecords } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[]; 
  meetings: Meeting[]; 
  kpis?: KPI[];
  config: AppConfig;
  onCreateTicket: (ticket: Ticket) => Promise<void>;
  onUpdateTicket: (ticketId: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility?: 'public' | 'internal') => void;
  onDeleteTicket: (ticketId: string) => Promise<void>;
  onUpdateServices: (services: ServiceOption[]) => void;
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateCustomers: (customers: Customer[]) => void; 
  onEditCustomer: (id: string, updates: Partial<Customer>) => Promise<void>;
  onDeleteCustomer: (id: string) => Promise<void>;
  onUpdateConfig: (config: AppConfig) => void;
  onLogout: () => void;
  lang: Language;
}

export const AdminDashboard: React.FC<Props> = ({ 
  currentUser,
  tickets, 
  services, 
  personnel, 
  customers,
  messages,
  tasks,
  meetings,
  kpis = [],
  config,
  onCreateTicket,
  onUpdateTicket,
  onDeleteTicket,
  onUpdateServices,
  onUpdatePersonnel,
  onUpdateCustomers,
  onEditCustomer,
  onDeleteCustomer,
  onUpdateConfig,
  onLogout,
  lang
}) => {
  const safeRoles = currentUser?.roles || [];
  const isAdmin = safeRoles.includes('مدیر');
  const isMaster = currentUser?.username === 'master';

  const canManageInvoices = isAdmin || isMaster || currentUser?.permissions?.canIssueInvoices; 
  const canAssign = isAdmin || isMaster || currentUser?.permissions?.canAssign;
  const hasCustomerAccess = isAdmin || isMaster || currentUser?.permissions?.canViewCustomers;
  const hasTariffAccess = isAdmin || isMaster || currentUser?.permissions?.canViewTariffs;
  const canViewAllTickets = isAdmin || isMaster || currentUser?.permissions?.canViewAllTickets;

  const [activeTab, setActiveTab] = useState<'overview' | 'projects' | 'services' | 'personnel' | 'customers' | 'settings' | 'accounting' | 'messages' | 'tasks' | 'meetings' | 'logs' | 'reports' | 'kpi' | 'forms' | 'sales' | 'staff_reports' | 'goals'>('overview');
  const [filterMode, setFilterMode] = useState<'all' | 'my' | 'history'>(canViewAllTickets ? 'all' : 'my');
  const [statusFilter, setStatusFilter] = useState<TicketStatus | 'all'>('all');
  const [globalSearch, setGlobalSearch] = useState(''); 
  const [currentPage, setCurrentPage] = useState(1);
  const ITEMS_PER_PAGE = 10;

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [activeModalTab, setActiveModalTab] = useState<'info' | 'project'>('info');
  const [newComment, setNewComment] = useState('');
  const [commentVisibility, setCommentVisibility] = useState<'public' | 'internal'>('public'); 

