                                                    <div className={`w-3 h-3 rounded-full mt-1.5 ring-4 ring-white ${entry.type === 'creation' ? 'bg-green-500' : entry.type === 'status_change' ? 'bg-blue-500' : 'bg-gray-400'}`}></div>
