}</option>)}</select></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.customer}</label><input required className="w-full px-3 py-2 border rounded-lg" value={newProjectData.customerName} onChange={e => setNewProjectData({...newProjectData, customerName: e.target.value})} /></div><div><label className="block text-sm font-bold text-gray-700 mb-1">{t.phone}</label><input required className="w-full px-3 py-2 border rounded-lg" value={newProjectData.phoneNumber} onChange={e => setNewProjectData({...newProjectData, phoneNumber: e.target.value})} /></div></div><div className="flex gap-3 pt-4"><button type="button" onClick={() => setShowNewProjectModal(false)} className="flex-1 py-2.5 bg-gray-100 rounded-xl">Cancel</button><button type="submit" className="flex-1 py-2.5 bg-purple-600 text-white rounded-xl font-bold">Create</button></div></form></div></div>
