              setCustomForms(allowedForms);
          });
          return () => unsubForms();
      }
  }, [activeTab, currentUser]);

  const getServiceTitle = (id: string) => {
      const s = services.find(s => s.id === id);
      if (!s) return id;
      return lang === 'en' && s.titleEn ? s.titleEn : s.title;
  };

  const getStatusBadge = (status: TicketStatus) => {
    switch(status) {
      case TicketStatus.SUBMITTED: return 'bg-blue-50 text-blue-700';
      case TicketStatus.PROCESSING: return 'bg-purple-50 text-purple-700';
      case TicketStatus.IN_PROGRESS: return 'bg-amber-50 text-amber-700';
      case TicketStatus.COMPLETED: return 'bg-emerald-50 text-emerald-700';
      case TicketStatus.CANCELLED: return 'bg-gray-100 text-gray-500 line-through';
      default: return 'bg-gray-50 text-gray-700';
    }
  };

  const filteredTickets = useMemo(() => {
      return [...tickets].filter(t => {
      const isArchived = t.status === TicketStatus.COMPLETED || t.status === TicketStatus.CANCELLED;
      if (filterMode === 'history') { if (!isArchived) return false; } else { if (isArchived) return false; if (!canViewAllTickets || filterMode === 'my') { if (!(t.assignedTo === currentUser.id || t.projectData?.teamMemberIds?.includes(personnel.find(p => p.id === currentUser.id)?.id || ''))) return false; } }
      if (statusFilter !== 'all' && t.status !== statusFilter) return false;
      if (globalSearch.trim()) {
          const term = globalSearch.toLowerCase();
          const matchesId = (t.id || '').toLowerCase().includes(term);
          const matchesCustomer = (t.customerName || '').toLowerCase().includes(term);
          const matchesCompany = (t.companyName || '').toLowerCase().includes(term); 
          const matchesPhone = (t.phoneNumber || '').includes(term);
          const matchesService = (getServiceTitle(t.serviceId) || '').toLowerCase().includes(term);
          const matchesDesc = (t.description || '').toLowerCase().includes(term);
          if (!matchesId && !matchesCustomer && !matchesCompany && !matchesPhone && !matchesService && !matchesDesc) return false;
      }
      return true;
    }).sort((a, b) => { if (a.priority === 'High' && b.priority !== 'High') return -1; if (a.priority !== 'High' && b.priority === 'High') return 1; return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(); });
  }, [tickets, filterMode, statusFilter, globalSearch, canViewAllTickets, currentUser.id, personnel]);

  const totalPages = Math.ceil(filteredTickets.length / ITEMS_PER_PAGE);
  const paginatedTickets = filteredTickets.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
  const activeProjects = tickets.filter(t => t.projectData?.isActive === true).filter(t => { if (canViewAllTickets) return true; return t.assignedTo === currentUser.id || t.projectData?.teamMemberIds?.includes(currentUser.id); });

  const handleAddComment = async () => { if (!selectedTicket || !newComment.trim()) return; onUpdateTicket(selectedTicket.id, {}, currentUser.fullName, newComment, commentVisibility); logSystemAction('UPDATE', 'Ticket', `Comment added to ticket ${selectedTicket.id}`, currentUser.fullName, selectedTicket.id); setNewComment(''); setCommentVisibility('public'); };
  const handleQuickReportAdd = () => { if (!quickReportText.trim()) return; setQuickReportItems([...quickReportItems, quickReportText.trim()]); setQuickReportText(''); };
  const handleSubmitQuickReport = async () => { if (quickReportItems.length === 0) return; setIsSavingQuickReport(true); const report: PerformanceReport = { id: `rep-${Date.now()}`, userId: currentUser.id, userName: currentUser.fullName, type: 'daily', date: new Date().toISOString().split('T')[0], content: 'داشبورد', completedTasks: quickReportItems, status: 'submitted', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; await saveReport(report); setQuickReportItems([]); setIsSavingQuickReport(false); alert('گزارش ثبت شد.'); };
  const handleStartEdit = () => { if (!selectedTicket) return; setEditingTicketData({ customerName: selectedTicket.customerName, companyName: selectedTicket.companyName, phoneNumber: selectedTicket.phoneNumber, whatsappNumber: selectedTicket.whatsappNumber, location: selectedTicket.location, businessType: selectedTicket.businessType, description: selectedTicket.description, serviceId: selectedTicket.serviceId }); setIsEditingTicket(true); };
  const handleSaveEdit = () => { if (!selectedTicket) return; onUpdateTicket(selectedTicket.id, editingTicketData, currentUser.fullName, 'Edit Basic Info'); logSystemAction('UPDATE', 'Ticket', `Edited ticket ${selectedTicket.id}`, currentUser.fullName, selectedTicket.id); setIsEditingTicket(false); };
  const handleDelete = async (id: string) => { if (!id) return; if (window.confirm('Delete?')) { await onDeleteTicket(id); if (selectedTicketId === id) setSelectedTicketId(null); } };
  const handleUpdateTicketStatus = (status: TicketStatus) => { if (!selectedTicket) return; onUpdateTicket(selectedTicket.id, { status }, currentUser.fullName); };
  const handleAssignTicket = async () => { if (!selectedTicket) return; if (tempAssignedTo === selectedTicket.assignedTo) return; onUpdateTicket(selectedTicket.id, { assignedTo: tempAssignedTo }, currentUser.fullName, 'Assigned'); logSystemAction('UPDATE', 'Ticket', `Assigned ${selectedTicket.id}`, currentUser.fullName, selectedTicket.id); alert('ارجاع شد.'); };
  const handleSaveProject = () => { if (!selectedTicket) return; onUpdateTicket(selectedTicket.id, { projectData: { ...projectForm, isActive: true } }, currentUser.fullName, 'Project Updated'); alert('ذخیره شد.'); };
  const handleRestore = async (log: SystemLog) => { if (window.confirm('Restore?')) { const success = await restoreEntityFromLog(log); alert(success ? 'Restored.' : 'Failed.'); } };

  // --- NEW ACCOUNTING DASHBOARD RENDERER ---
  const renderAccountingDashboard = () => {
      // 1. Group records by month for the selected year
      const yearRecords = salesRecords.filter(r => r.depositDate.startsWith(accountingYear));

      const monthlyData = Array.from({ length: 12 }, (_, i) => {
          const monthKey = `${accountingYear}-${String(i + 1).padStart(2, '0')}`;
          const monthRecords = yearRecords.filter(r => r.depositDate.startsWith(monthKey));
          const gross = monthRecords.reduce((sum, r) => sum + r.saleAmount, 0);
          const comm = monthRecords.reduce((sum, r) => sum + r.commissionAmount, 0);
          const net = gross - comm;
          return { monthName: new Date(accountingYear, i).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US', { month: 'long' }), gross, comm, net };
      });

      // 2. Section Profitability (By Service)
      const servicePerformance: Record<string, { gross: number, net: number }> = {};
      yearRecords.forEach(r => {
          if (!servicePerformance[r.serviceTitle]) servicePerformance[r.serviceTitle] = { gross: 0, net: 0 };
          servicePerformance[r.serviceTitle].gross += r.saleAmount;
          servicePerformance[r.serviceTitle].net += (r.saleAmount - r.commissionAmount);
      });

      const sortedSectors = Object.entries(servicePerformance).sort((a, b) => b[1].net - a[1].net);
      const topSector = sortedSectors[0];

      const totalYearlyGross = yearRecords.reduce((sum, r) => sum + r.saleAmount, 0);
      const totalYearlyNet = yearRecords.reduce((sum, r) => sum + (r.saleAmount - r.commissionAmount), 0);
      const totalCommissions = yearRecords.reduce((sum, r) => sum + r.commissionAmount, 0);

      const maxMonthNet = Math.max(...monthlyData.map(m => m.net), 1);

      return (
          <div className="space-y-8 animate-fade-in pb-12">
              {/* Header & Year Filter */}
              <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl border border-gray-100 shadow-sm gap-4">
                  <div className="flex items-center gap-4">
                      <div className="bg-indigo-600 text-white p-3 rounded-2xl shadow-lg shadow-indigo-100"><IconWallet className="w-6 h-6" /></div>
                      <div>
                          <h2 className="text-xl font-black text-gray-900">{t.accounting}</h2>
                          <p className="text-xs text-gray-500 font-bold">{t.sub}</p>
                      </div>
                  </div>
                  <div className="flex items-center gap-2 bg-gray-50 px-4 py-2 rounded-2xl border border-gray-200">
                      <span className="text-xs font-bold text-gray-400">سال مالی:</span>
                      <select className="bg-transparent font-black text-indigo-600 outline-none" value={accountingYear} onChange={e => setAccountingYear(e.target.value)}>
                          {Array.from({ length: 5 }, (_, i) => (new Date().getFullYear() - i).toString()).map(y => <option key={y} value={y}>{y}</option>)}
                      </select>
                  </div>
              </div>

              {/* Top Stats */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                  <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
                      <div className="text-gray-400 text-[10px] font-black uppercase mb-1">{t.revenueTotal}</div>
                      <div className="text-2xl font-black text-gray-900">{totalYearlyGross.toLocaleString()} <span className="text-xs font-normal text-gray-400">{t.rial}</span></div>
                  </div>
                  <div className="bg-indigo-600 p-6 rounded-3xl text-white shadow-xl shadow-indigo-100">
                      <div className="text-indigo-200 text-[10px] font-black uppercase mb-1">{t.netProfit}</div>
                      <div className="text-2xl font-black">{totalYearlyNet.toLocaleString()} <span className="text-xs font-normal opacity-60">{t.rial}</span></div>
                  </div>
                  <div className="bg-white p-6 rounded-3xl border border-gray-100 shadow-sm">
                      <div className="text-rose-400 text-[10px] font-black uppercase mb-1">{t.commissions}</div>
                      <div className="text-2xl font-black text-rose-600">{totalCommissions.toLocaleString()} <span className="text-xs font-normal text-gray-400">{t.rial}</span></div>
                  </div>
                  <div className="bg-emerald-50 p-6 rounded-3xl border border-emerald-100 shadow-sm">
                      <div className="text-emerald-700 text-[10px] font-black uppercase mb-1">{t.mostProfitable}</div>
                      <div className="text-sm font-black text-emerald-900 truncate">{topSector ? topSector[0] : '-'}</div>
                  </div>
              </div>

              {/* Monthly Performance Visualizer */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                  <div className="lg:col-span-2 bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
                      <div className="p-6 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                          <h3 className="font-black text-gray-800 flex items-center gap-2"><IconTrendingUp className="w-5 h-5 text-indigo-600" /> {t.monthlyPerformance}</h3>
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{accountingYear}</span>
                      </div>
                      <div className="p-8 space-y-6">
                          {monthlyData.map((m, idx) => (
                              <div key={idx} className="flex items-center gap-4 group">
                                  <div className="w-20 text-xs font-black text-gray-500 uppercase">{m.monthName}</div>
                                  <div className="flex-grow h-6 bg-gray-50 rounded-full relative overflow-hidden flex items-center px-1">
                                      <div className="h-4 bg-gradient-to-l from-indigo-600 to-blue-500 rounded-full transition-all duration-1000 group-hover:from-indigo-500" style={{ width: `${(m.net / maxMonthNet) * 100}%` }}></div>
                                      {m.net > 0 && <span className="absolute rtl:left-3 ltr:right-3 text-[9px] font-black text-indigo-900 opacity-0 group-hover:opacity-100 transition-opacity">{m.net.toLocaleString()}</span>}
                                  </div>
                                  <div className="w-24 text-right text-[10px] font-black text-gray-400">{m.gross.toLocaleString()}</div>
                              </div>
                          ))}
                      </div>
                  </div>

                  {/* Section Profitability Leaderboard */}
                  <div className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden flex flex-col">
                      <div className="p-6 border-b border-gray-50 bg-gray-50/50">
                          <h3 className="font-black text-gray-800 flex items-center gap-2"><IconTrophy className="w-5 h-5 text-amber-500" /> آنالیز سوددهی بخش‌ها</h3>
                      </div>
                      <div className="p-6 space-y-4">
                          {sortedSectors.map(([title, stats], idx) => (
                              <div key={title} className={`p-4 rounded-2xl border transition-all ${idx === 0 ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100'}`}>
                                  <div className="flex justify-between items-start mb-2">
                                      <div className="font-black text-sm text-gray-800 truncate max-w-[120px]">{title}</div>
                                      <div className={`text-[10px] font-black px-2 py-0.5 rounded-full ${idx === 0 ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-400'}`}>Rank #{idx + 1}</div>
                                  </div>
                                  <div className="flex justify-between text-[10px] mb-1">
                                      <span className="text-gray-400 font-bold">{t.grossSales}</span>
                                      <span className="text-gray-600 font-black">{stats.gross.toLocaleString()}</span>
                                  </div>
                                  <div className="flex justify-between text-[10px]">
                                      <span className="text-indigo-600 font-bold">{t.companyShare}</span>
                                      <span className="text-indigo-900 font-black">{stats.net.toLocaleString()}</span>
                                  </div>
                                  <div className="w-full bg-gray-200 h-1 rounded-full mt-3 overflow-hidden">
                                      <div className="bg-indigo-500 h-full" style={{ width: `${(stats.net / totalYearlyNet) * 100}%` }}></div>
                                  </div>
                              </div>
                          ))}
                          {sortedSectors.length === 0 && <div className="py-20 text-center text-gray-400 text-sm font-bold">داده‌ای برای تحلیل وجود ندارد.</div>}
                      </div>
                  </div>
              </div>
          </div>
      );
  };

