                                        <span className="text-xs font-black text-rose-600">{exp.amount.toLocaleString()}</span>
                                        <button onClick={() => deleteExpense(exp.id, currentUser.fullName)} className="text-gray-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><IconTrash className="w-3 h-3" /></button>
