const INITIAL_CATEGORIES = [
    { id: 'cat1', title: 'اهداف تجاری', color: 'bg-indigo-500', type: 'business' as const },
    { id: 'cat2', title: 'توسعه مهارت', color: 'bg-emerald-500', type: 'personal' as const },
    { id: 'cat3', title: 'سلامت و سبک زندگی', color: 'bg-rose-400', type: 'personal' as const },
    { id: 'cat4', title: 'پروژه‌های کلیدی', color: 'bg-blue-400', type: 'business' as const },
    { id: 'cat5', title: 'سایر اولویت‌ها', color: 'bg-slate-400', type: 'personal' as const }
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
    const [selectedUserId, setSelectedUserId] = useState<string>(currentUser.id);
    const [activePeriod, setActivePeriod] = useState<GoalPeriod>('daily');
    const [currentUserGoals, setCurrentUserGoals] = useState<UserGoals | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isExporting, setIsExporting] = useState(false);
    const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);
    const [isEditingVision, setIsEditingVision] = useState(false);
    const [tempVision, setTempVision] = useState('');

    const [editingId, setEditingId] = useState<string | null>(null);
    const [editValue, setEditValue] = useState('');

    const posterRef = useRef<HTMLDivElement>(null);
    const canEdit = selectedUserId === currentUser.id;

    useEffect(() => {
        setIsLoading(true);
        const unsub = subscribeToUserGoals(selectedUserId, activePeriod, (goals) => {
            if (goals) {
                setCurrentUserGoals(goals);
                setTempVision(goals.visionNote || '');
            } else {
                setCurrentUserGoals({
                    id: `${selectedUserId}_${activePeriod}`,
                    userId: selectedUserId,
                    userName: personnel.find(p => p.id === selectedUserId)?.fullName || 'User',
                    period: activePeriod,
                    lastUpdated: new Date().toISOString(),
                    categories: INITIAL_CATEGORIES.map(c => ({ ...c, tasks: [] })),
                    visionNote: 'نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.'
                });
                setTempVision('نظم در اجرا، تفاوت میان سازمان‌های خوب و سازمان‌های عالی است.');
            }
            setIsLoading(false);
        });
        return () => unsub();
    }, [selectedUserId, activePeriod, personnel]);

    const stats = useMemo(() => {
        if (!currentUserGoals) return { done: 0, total: 0, percent: 0 };
        let done = 0, total = 0;
        currentUserGoals.categories.forEach(c => {
            c.tasks.forEach(t => {
                total++;
                if (t.isCompleted) done++;
            });
        });
        return { done, total, percent: total > 0 ? Math.round((done / total) * 100) : 0 };
    }, [currentUserGoals]);

    const { activeView, historyView } = useMemo(() => {
        if (!currentUserGoals) return { activeView: [], historyView: [] };
        const history: (GoalTask & { categoryTitle: string, categoryColor: string })[] = [];
        const active = currentUserGoals.categories.map(cat => {
            const activeTasks = cat.tasks.filter(t => !t.isCompleted);
            cat.tasks.filter(t => t.isCompleted).forEach(ct => {
                history.push({ ...ct, categoryTitle: cat.title, categoryColor: cat.color });
            });
            return { ...cat, tasks: activeTasks };
        });
        return { activeView: active, historyView: history };
    }, [currentUserGoals]);

    const t = {
        fa: {
            title: 'نقشه راه موفقیت',
            visionTitle: 'چشم‌انداز و انگیزه من',
            visionHint: 'برای ویرایش کلیک کنید...',
            daily: 'امروز', weekly: 'هفته', monthly: 'ماه', yearly: 'سال', five_year: '۵ ساله',
            addGoal: 'هدف جدید',
            empty: 'لیست اهداف جاری خالی است.',
            hallOfFame: 'تالار دستاوردها',
            progress: 'تحقق اهداف',
            print: 'خروجی پوستر',
            save: 'ذخیره'
        },
        en: {
            title: 'Success Roadmap',
            visionTitle: 'My Vision & Motivation',
            visionHint: 'Click to edit...',
            daily: 'Daily', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly', five_year: '5-Year',
            addGoal: 'New Goal',
            empty: 'No active goals.',
            hallOfFame: 'Hall of Fame',
            progress: 'Total Progress',
            print: 'Export Poster',
            save: 'Save'
        }
    }[lang];

    const syncGoals = (updatedCategories: GoalCategory[], newVision?: string) => {
        if (!currentUserGoals) return;
        const updatedGoals = { 
            ...currentUserGoals, 
            categories: updatedCategories, 
            visionNote: newVision !== undefined ? newVision : currentUserGoals.visionNote,
            lastUpdated: new Date().toISOString() 
        };
        setCurrentUserGoals(updatedGoals);
        saveUserGoals(updatedGoals);
    };

    const handleAddTask = (catId: string) => {
        const text = window.prompt(lang === 'fa' ? 'عنوان هدف:' : 'Goal Title:');
        if (!text || !currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: [...c.tasks, { id: `t-${Date.now()}`, text, isCompleted: false, subTasks: [] }] } : c);
        syncGoals(updated);
    };

    const toggleTask = (catId: string, taskId: string) => {
        if (!currentUserGoals) return;
        const updated = currentUserGoals.categories.map(c => c.id === catId ? { ...c, tasks: c.tasks.map(t => t.id === taskId ? { ...t, isCompleted: !t.isCompleted } : t) } : c);
        syncGoals(updated);
    };

    const handleSaveVision = () => {
        if (!currentUserGoals) return;
        syncGoals(currentUserGoals.categories, tempVision);
        setIsEditingVision(false);
    };

    const handleExportImage = async () => {
        if (!posterRef.current || isExporting) return;
        setIsExporting(true);
        try {
            const dataUrl = await htmlToImage.toPng(posterRef.current, { quality: 1, pixelRatio: 2, backgroundColor: '#ffffff' });
            const link = document.createElement('a');
            link.download = `Success-Roadmap.png`;
            link.href = dataUrl;
            link.click();
        } catch (err) { alert('Error!'); } finally { setIsExporting(false); }
    };

    return (
        <div className="space-y-8 animate-fade-in pb-20">
            {/* Minimal Header & Period Switcher */}
            <div className="flex flex-col lg:flex-row justify-between items-center gap-6">
                <div>
                    <h2 className="text-3xl font-black text-gray-900 tracking-tight flex items-center gap-3">
                        <IconTarget className="w-8 h-8 text-indigo-600" />
                        {t.title}
                    </h2>
                    <p className="text-sm text-gray-500 mt-1 font-medium">سلسله مراتب اهداف و پایش عملکرد فردی</p>
                </div>

                <div className="flex flex-wrap items-center gap-4">
                    <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
                        {['daily', 'weekly', 'monthly', 'yearly', 'five_year'].map(p => (
                            <button key={p} onClick={() => setActivePeriod(p as GoalPeriod)} className={`px-4 py-2 rounded-xl text-xs font-black transition-all ${activePeriod === p ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-gray-400 hover:bg-gray-50'}`}>{t[p as keyof typeof t.fa]}</button>
                        ))}
                    </div>
                    <button onClick={handleExportImage} className="p-3 bg-white border border-gray-200 text-gray-400 hover:text-indigo-600 rounded-2xl shadow-sm transition-all hover:scale-110"><IconPrinter className="w-5 h-5" /></button>
                </div>
            </div>

            {/* Vision Note Card (Editable) */}
            <div className="bg-gradient-to-r from-indigo-600 to-blue-700 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
                <IconShield className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10 rotate-12" />
                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-4 opacity-80 uppercase tracking-widest text-[10px] font-black">
                        <IconBulb className="w-4 h-4" /> {t.visionTitle}
                    </div>
                    {isEditingVision && canEdit ? (
                        <div className="space-y-4">
                            <textarea 
                                className="w-full bg-white/10 backdrop-blur-md border border-white/20 rounded-2xl p-4 text-white text-lg font-bold outline-none focus:bg-white/20 transition-all placeholder:text-white/40"
                                value={tempVision}
                                onChange={e => setTempVision(e.target.value)}
                                rows={2}
                                autoFocus
                            />
                            <div className="flex justify-end gap-2">
                                <button onClick={() => setIsEditingVision(false)} className="px-4 py-1.5 text-xs font-bold opacity-60">انصراف</button>
                                <button onClick={handleSaveVision} className="px-6 py-1.5 bg-white text-indigo-600 rounded-xl text-xs font-black shadow-lg shadow-indigo-900/20">{t.save}</button>
                            </div>
                        </div>
                    ) : (
                        <p 
                            onClick={() => canEdit && setIsEditingVision(true)}
                            className={`text-xl md:text-2xl font-black leading-relaxed italic ${canEdit ? 'cursor-pointer hover:opacity-80 transition-opacity' : ''}`}
                        >
                            "{currentUserGoals?.visionNote || t.visionHint}"
                        </p>
                    )}
                </div>
            </div>

            {/* Main Goals Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {activeView.map(cat => (
                    <div key={cat.id} className="bg-white rounded-[2.5rem] border border-gray-100 shadow-xl overflow-hidden flex flex-col group/cat">
                        <div className="p-6 border-b border-gray-50 flex justify-between items-center bg-gray-50/50">
                            <div className="flex items-center gap-3">
                                <div className={`w-3 h-3 rounded-full ${cat.color} shadow-sm`}></div>
                                <h3 className="font-black text-gray-800 text-sm uppercase tracking-wider">{cat.title}</h3>
                            </div>
                            {canEdit && (
                                <button onClick={() => handleAddTask(cat.id)} className="w-8 h-8 rounded-xl bg-white border border-gray-200 text-gray-400 hover:text-indigo-600 hover:border-indigo-200 flex items-center justify-center transition-all shadow-sm">
                                    <IconPlus className="w-4 h-4" />
                                </button>
                            )}
                        </div>

                        <div className="p-6 space-y-4 flex-grow overflow-y-auto max-h-[400px] custom-scrollbar">
                            {cat.tasks.length === 0 ? (
                                <div className="py-10 text-center text-gray-300 text-xs font-bold italic">{t.empty}</div>
                            ) : (
                                cat.tasks.map(task => (
                                    <div key={task.id} className="flex items-start gap-4 p-4 rounded-3xl bg-gray-50/30 border border-gray-50 hover:bg-white hover:shadow-md transition-all group/task">
                                        <button 
                                            onClick={() => canEdit && toggleTask(cat.id, task.id)}
                                            className={`w-6 h-6 rounded-xl border-2 flex items-center justify-center shrink-0 transition-all ${task.isCompleted ? 'bg-green-500 border-green-500 text-white' : 'border-gray-200 bg-white hover:border-indigo-400'}`}
                                        >
                                            {task.isCompleted && <IconCheck className="w-4 h-4" />}
                                        </button>
                                        <div className="flex-grow min-w-0">
                                            <span className="text-sm font-bold text-gray-700 leading-snug block">{task.text}</span>
                                        </div>
                                        {canEdit && (
                                            <button onClick={() => { if(confirm('حذف شود؟')) syncGoals(currentUserGoals!.categories.map(c => c.id === cat.id ? {...c, tasks: c.tasks.filter(t => t.id !== task.id)} : c)) }} className="p-1.5 text-gray-300 hover:text-red-500 opacity-0 group-hover/task:opacity-100 transition-opacity">
                                                <IconTrash className="w-3 h-3" />
                                            </button>
                                        )}
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* Hall of Fame - History */}
            {historyView.length > 0 && (
                <div className="bg-white rounded-[3rem] border border-gray-100 p-10 shadow-2xl shadow-gray-200/50">
                    <div className="flex items-center gap-4 mb-10 border-b border-gray-100 pb-8">
                        <div className="p-4 bg-amber-50 text-amber-500 rounded-3xl shadow-inner"><IconTrophy className="w-8 h-8" /></div>
                        <div>
                            <h3 className="text-2xl font-black text-gray-900">{t.hallOfFame}</h3>
                            <p className="text-sm text-gray-400 font-medium">لیست دستاوردهای شما در بازه زمانی {t[activePeriod as keyof typeof t.fa]}</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        {historyView.map((goal, idx) => (
                            <div key={idx} className="p-5 rounded-3xl border border-gray-100 bg-gray-50 flex items-center gap-4 group transition-all hover:bg-white hover:shadow-lg">
                                <div className="w-10 h-10 rounded-2xl bg-white flex items-center justify-center text-amber-500 shadow-sm"><IconStar className="w-5 h-5 fill-current" /></div>
                                <div className="min-w-0">
                                    <h4 className="text-sm font-black text-gray-400 line-through truncate">{goal.text}</h4>
                                    <span className="text-[10px] font-bold text-gray-300 uppercase tracking-tighter">{goal.categoryTitle}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* --- Hidden Poster for Export (Design updated to be minimal) --- */}
            <div style={{ position: 'fixed', left: '-9999px', top: 0 }}>
                <div ref={posterRef} className="bg-white p-20 flex flex-col" style={{ width: '800px', height: '1100px' }}>
                    <div className="flex justify-between items-start mb-20">
                        <div>
                            <h1 className="text-5xl font-black text-gray-900 mb-2 tracking-tighter">SUCCESS MAP</h1>
                            <p className="text-gray-400 font-bold uppercase tracking-[0.3em]">{activePeriod} STRATEGIC OBJECTIVES</p>
                        </div>
                        <div className="text-right">
                            <div className="text-6xl font-black text-indigo-600">{stats.percent}%</div>
                            <p className="text-xs font-black text-gray-300 tracking-widest">PROGRESS RATE</p>
                        </div>
                    </div>
                    <div className="bg-gray-900 p-10 rounded-3xl text-white mb-16 shadow-2xl">
                        <p className="text-2xl font-black italic opacity-90 leading-relaxed text-center">"{currentUserGoals?.visionNote}"</p>
                    </div>
                    <div className="flex-grow grid grid-cols-2 gap-16">
                        {currentUserGoals?.categories.map(cat => (
                            <div key={cat.id} className="space-y-6">
                                <div className="flex items-center gap-3 border-b-2 border-gray-100 pb-3">
                                    <div className={`w-3 h-3 rounded-full ${cat.color}`}></div>
                                    <h3 className="text-sm font-black text-gray-400 uppercase tracking-[0.2em]">{cat.title}</h3>
                                </div>
                                <div className="space-y-4">
                                    {cat.tasks.map(t => (
                                        <div key={t.id} className="flex gap-4 items-start">
                                            <div className={`w-5 h-5 rounded-lg border-2 mt-1 shrink-0 ${t.isCompleted ? 'bg-indigo-600 border-indigo-600' : 'border-gray-200'}`}></div>
                                            <span className={`text-lg font-bold ${t.isCompleted ? 'line-through text-gray-300' : 'text-gray-800'}`}>{t.text}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                    <div className="pt-20 border-t border-gray-100 flex justify-between items-end">
                        <div className="max-w-[60%]">
                            <p className="text-[10px] font-black text-gray-300 uppercase mb-2">Authenticated By</p>
                            <h2 className="text-2xl font-black text-gray-900">{currentUserGoals?.userName}</h2>
                        </div>
                        <IconShield className="w-16 h-16 text-indigo-600 opacity-20" />
                    </div>
                </div>
            </div>
        </div>
    );
};

