import React, { useState, useEffect } from 'react';
import { Personnel, SalesRecord, ServiceOption, Currency, DesignerPayment } from '../types';
import { IconMoney, IconPlus, IconChart, IconUsers, IconTrophy, IconPercent, IconEdit, IconCheck, IconSearch, IconBriefcase, IconCalendar, IconRefreshCw, IconTrash, IconWallet, IconPalette, IconStar } from './Icons';
import { saveSalesRecord, subscribeToSalesRecords, updateSalesRecord, deleteSalesRecord, saveDesignerPayment, updateDesignerPayment, deleteDesignerPayment, subscribeToDesignerPayments } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[];
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateServices: (services: ServiceOption[]) => void;
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, onUpdatePersonnel, onUpdateServices, lang }) => {
  const [activeTab, setActiveTab] = useState<'new_sale' | 'my_sales' | 'all_sales' | 'designers' | 'commissions' | 'leaderboard'>('my_sales');
  const [salesRecords, setSalesRecords] = useState<SalesRecord[]>([]);
  const [designerPayments, setDesignerPayments] = useState<DesignerPayment[]>([]);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const SALES_PER_PAGE = 10;

  // Filtering States
  const [selectedMonth, setSelectedMonth] = useState<string>(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [filterUserId, setFilterUserId] = useState<string>('');

  const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');

  // New Sale Form State
  const [newSale, setNewSale] = useState({
      serviceId: '',
      salespersonId: currentUser.id,
      customerName: '',
      amount: '',
      currency: 'IRR' as Currency,
      depositAccount: '',
      depositDate: new Date().toISOString().split('T')[0],
      notes: ''
  });

  // New Designer Payment Form State
  const [newDesignerPay, setNewDesignerPay] = useState({
      designerId: '',
      projectTitle: '',
      amount: '',
      currency: 'IRR' as Currency,
      date: new Date().toISOString().split('T')[0],
      notes: ''
  });

  // Edit States
  const [editingSale, setEditingSale] = useState<SalesRecord | null>(null);
  const [editingDesignerPay, setEditingDesignerPay] = useState<DesignerPayment | null>(null);

  useEffect(() => {
      const unsubSales = subscribeToSalesRecords(setSalesRecords);
      const unsubDesigners = subscribeToDesignerPayments(setDesignerPayments);
      return () => { unsubSales(); unsubDesigners(); };
  }, []);

  const t = {
      fa: {
          header: 'مدیریت فروش و کمیسیون',
          sub: 'ثبت تراکنش‌ها، محاسبه کمیسیون و گزارش‌گیری',
          tabs: {
              new: 'ثبت فروش جدید',
              my: 'فروش‌های من',
              all: 'کل فروش‌ها',
              designers: 'حق‌الزحمه طراحان',
              settings: 'تنظیمات کمیسیون',
              top: 'رتبه‌بندی'
          },
          designers: {
              new: 'ثبت پرداختی به طراح',
              select: 'انتخاب طراح',
              project: 'عنوان پروژه / طرح',
              amount: 'مبلغ حق‌الزحمه',
              status: 'وضعیت پرداخت',
              rankings: 'رتبه‌بندی همکاری با طراحان',
              collabPower: 'سطح همکاری (بر اساس دریافتی)',
              totalEarned: 'کل دریافتی طراح',
              projectCount: 'تعداد پروژه‌ها'
          },
          form: {
              salesperson: 'فروشنده',
              service: 'خدمت فروخته شده',
              customer: 'نام مشتری',
              amount: 'مبلغ واریزی',
              currency: 'ارز',
              account: 'حساب مقصد',
              date: 'تاریخ واریز',
              notes: 'توضیحات (اختیاری)',
              submit: 'ثبت نهایی',
              calcCommission: 'کمیسیون تخمینی:',
              success: 'عملیات با موفقیت انجام شد.'
          },
          table: {
              row: 'ردیف',
              seller: 'فروشنده',
              service: 'سرویس',
              customer: 'مشتری',
              amount: 'مبلغ',
              commission: 'سهم فرد',
              date: 'تاریخ',
              status: 'وضعیت تسویه',
              actions: 'عملیات',
              paid: 'پرداخت شده',
              pending: 'در انتظار پرداخت',
              prev: 'قبلی',
              next: 'بعدی'
          }
      },
      en: {
          header: 'Sales & Commissions',
          sub: 'Track sales, commissions, and staff payouts',
          tabs: {
              new: 'New Sale',
              my: 'My Sales',
              all: 'All Sales',
              designers: 'Designers Payouts',
              settings: 'Comm. Settings',
              top: 'Leaderboard'
          },
          designers: {
              new: 'Record Designer Payout',
              select: 'Select Designer',
              project: 'Project Title',
              amount: 'Fee Amount',
              status: 'Payout Status',
              rankings: 'Designer Collaboration Ranking',
              collabPower: 'Collaboration Level',
              totalEarned: 'Total Earned',
              projectCount: 'Projects'
          },
          form: {
              salesperson: 'Personnel',
              service: 'Service',
              customer: 'Customer',
              amount: 'Amount',
              currency: 'Currency',
              account: 'Account',
              date: 'Date',
              notes: 'Notes',
              submit: 'Record Entry',
              calcCommission: 'Calculated:',
              success: 'Successfully recorded.'
          }
      }
  }[lang];

  const designers = personnel.filter(p => p.roles.some(r => r.includes('طراح') || r.toLowerCase().includes('design')));
  const salesPersonnel = personnel.filter(p => p.roles.some(r => r.includes('فروش') || r.toLowerCase().includes('sales')) || p.username === 'master');

  const handleAmountInput = (val: string) => {
      let normalized = val.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d).toString()).replace(/\D/g, '');
      return normalized.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };

  const handleDesignerPaySubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newDesignerPay.designerId || !newDesignerPay.amount || !newDesignerPay.projectTitle) return;
      const amount = parseFloat(newDesignerPay.amount.replace(/,/g, ''));
      const designer = personnel.find(p => p.id === newDesignerPay.designerId);
      const record: DesignerPayment = {
          id: `dpay-${Date.now()}`,
          designerId: newDesignerPay.designerId,
          designerName: designer?.fullName || 'Unknown',
          projectTitle: newDesignerPay.projectTitle,
          amount: amount,
          currency: newDesignerPay.currency,
          date: newDesignerPay.date,
          isPaid: false,
          notes: newDesignerPay.notes,
          createdAt: new Date().toISOString(),
          recordedBy: currentUser.fullName
      };
      await saveDesignerPayment(record);
      alert(t.form.success);
      setNewDesignerPay({ ...newDesignerPay, amount: '', projectTitle: '', notes: '' });
  };

  const handleSaleSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newSale.amount || !newSale.serviceId || !newSale.customerName) return;
      const amount = parseFloat(newSale.amount.replace(/,/g, ''));
      const rate = 10; // Simple logic for example
      const record: SalesRecord = {
          id: `sale-${Date.now()}`,
          salespersonId: newSale.salespersonId,
          salespersonName: personnel.find(p => p.id === newSale.salespersonId)?.fullName || 'Unknown',
          serviceId: newSale.serviceId,
          serviceTitle: services.find(s => s.id === newSale.serviceId)?.title || 'Service',
          customerName: newSale.customerName,
          saleAmount: amount,
          currency: newSale.currency,
          commissionRate: rate,
          commissionAmount: (amount * rate) / 100,
          commissionPaid: false,
          depositAccount: newSale.depositAccount,
          depositDate: newSale.depositDate,
          notes: newSale.notes,
          createdAt: new Date().toISOString()
      };
      await saveSalesRecord(record);
      alert(t.form.success);
      setNewSale({ ...newSale, amount: '', customerName: '', notes: '' });
      setActiveTab('my_sales');
  };

  const designerRankings = useMemo(() => {
      return designers.map(d => {
          const payments = designerPayments.filter(p => p.designerId === d.id);
          const totalEarned = payments.reduce((acc, p) => acc + p.amount, 0);
          return { ...d, totalEarned, projectCount: payments.length };
      }).sort((a, b) => b.totalEarned - a.totalEarned);
  }, [designers, designerPayments]);

  const displayDesignerPayments = designerPayments.filter(p => !selectedMonth || p.date.startsWith(selectedMonth));
  const filteredSales = salesRecords.filter(r => (activeTab === 'my_sales' ? r.salespersonId === currentUser.id : true) && (!selectedMonth || r.depositDate.startsWith(selectedMonth)));
  const displaySales = filteredSales.slice((currentPage - 1) * SALES_PER_PAGE, currentPage * SALES_PER_PAGE);

  return (
    <div className="space-y-6 animate-fade-in pb-20">
        <div className="flex flex-col lg:flex-row justify-between items-center bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-xl shadow-gray-200/50 gap-6">
            <div className="flex items-center gap-4">
                <div className="bg-indigo-600 text-white p-3 rounded-2xl shadow-lg shadow-indigo-100"><IconMoney className="w-6 h-6" /></div>
                <div><h2 className="text-xl font-black text-gray-900">{t.header}</h2><p className="text-sm text-gray-400 font-medium">{t.sub}</p></div>
            </div>
            <div className="flex bg-gray-100 p-1.5 rounded-2xl overflow-x-auto max-w-full no-scrollbar">
                <button onClick={() => setActiveTab('new_sale')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'new_sale' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.new}</button>
                <button onClick={() => setActiveTab('my_sales')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'my_sales' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.my}</button>
                {isMaster && (
                    <>
                        <button onClick={() => setActiveTab('all_sales')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'all_sales' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.all}</button>
                        <button onClick={() => setActiveTab('designers')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap flex items-center gap-2 ${activeTab === 'designers' ? 'bg-white shadow text-rose-600' : 'text-gray-400'}`}><IconPalette className="w-4 h-4" />{t.tabs.designers}</button>
                    </>
                )}
                <button onClick={() => setActiveTab('leaderboard')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'leaderboard' ? 'bg-white shadow text-amber-600' : 'text-gray-400'}`}>{t.tabs.top}</button>
            </div>
        </div>

        {/* Filters Area */}
        {(activeTab === 'my_sales' || activeTab === 'all_sales' || activeTab === 'designers' || activeTab === 'leaderboard') && (
            <div className="flex bg-white p-4 rounded-3xl border border-gray-100 shadow-sm gap-4 items-center">
                <IconCalendar className="w-5 h-5 text-gray-400" />
                <input type="month" className="outline-none text-sm font-black text-gray-800" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} />
                {selectedMonth && <button onClick={() => setSelectedMonth('')} className="text-red-400 hover:text-red-600"><IconRefreshCw className="w-4 h-4" /></button>}
            </div>
        )}

        {/* Tab Content: Designer Payments */}
        {activeTab === 'designers' && isMaster && (
            <div className="space-y-8 animate-fade-in">
                {/* Designer Leaderboard - Visualizing Collaboration */}
                <div className="bg-gradient-to-br from-rose-600 to-pink-700 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                    <IconPalette className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10 rotate-12" />
                    <h3 className="text-2xl font-black mb-8 flex items-center gap-3"><IconTrophy className="w-6 h-6 text-amber-300" /> {t.designers.rankings}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {designerRankings.map((d, idx) => (
                            <div key={d.id} className="bg-white/10 backdrop-blur-md p-5 rounded-[2rem] border border-white/20 flex flex-col gap-4 relative group hover:bg-white/20 transition-all">
                                <div className="flex justify-between items-start">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center font-black">{idx + 1}</div>
