import { saveSalesRecord, subscribeToSalesRecords, updateSalesRecord, deleteSalesRecord, saveDesignerPayment, updateDesignerPayment, deleteDesignerPayment, subscribeToDesignerPayments } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  services: ServiceOption[];
  onUpdatePersonnel: (personnel: Personnel[]) => void;
  onUpdateServices: (services: ServiceOption[]) => void;
  lang: Language;
}

export const SalesDashboard: React.FC<Props> = ({ currentUser, personnel, services, onUpdatePersonnel, onUpdateServices, lang }) => {
  const [activeTab, setActiveTab] = useState<'new_sale' | 'my_sales' | 'all_sales' | 'designers' | 'commissions' | 'leaderboard'>('my_sales');
  const [salesRecords, setSalesRecords] = useState<SalesRecord[]>([]);
  const [designerPayments, setDesignerPayments] = useState<DesignerPayment[]>([]);

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const SALES_PER_PAGE = 10;

  // Filtering States
  const [selectedMonth, setSelectedMonth] = useState<string>(new Date().toISOString().slice(0, 7)); // YYYY-MM
  const [filterUserId, setFilterUserId] = useState<string>('');

  const isMaster = currentUser.username === 'master' || currentUser.roles.includes('مدیر');

  // New Sale Form State
  const [newSale, setNewSale] = useState({
      serviceId: '',
      salespersonId: currentUser.id,
      customerName: '',
      amount: '',
      currency: 'IRR' as Currency,
      depositAccount: '',
      depositDate: new Date().toISOString().split('T')[0],
      notes: ''
  });

  // New Designer Payment Form State
  const [newDesignerPay, setNewDesignerPay] = useState({
      designerId: '',
      projectTitle: '',
      amount: '',
      currency: 'IRR' as Currency,
      date: new Date().toISOString().split('T')[0],
      notes: ''
  });

  // Edit States
  const [editingSale, setEditingSale] = useState<SalesRecord | null>(null);
  const [editingDesignerPay, setEditingDesignerPay] = useState<DesignerPayment | null>(null);

  useEffect(() => {
      const unsubSales = subscribeToSalesRecords(setSalesRecords);
      const unsubDesigners = subscribeToDesignerPayments(setDesignerPayments);
      return () => { unsubSales(); unsubDesigners(); };
  }, []);

  const t = {
      fa: {
          header: 'مدیریت فروش و کمیسیون',
          sub: 'ثبت تراکنش‌ها، محاسبه کمیسیون و گزارش‌گیری',
