              select: 'Select Designer',
              project: 'Project Title',
              amount: 'Fee Amount',
              status: 'Payout Status',
              rankings: 'Designer Collaboration Ranking',
              collabPower: 'Collaboration Level',
              totalEarned: 'Total Earned',
              projectCount: 'Projects'
          },
          form: {
              salesperson: 'Personnel',
              service: 'Service',
              customer: 'Customer',
