  const designers = personnel.filter(p => p.roles.some(r => r.includes('طراح') || r.toLowerCase().includes('design')));
  const salesPersonnel = personnel.filter(p => p.roles.some(r => r.includes('فروش') || r.toLowerCase().includes('sales')) || p.username === 'master');

  const handleAmountInput = (val: string) => {
      let normalized = val.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d).toString()).replace(/\D/g, '');
      return normalized.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };

  const handleDesignerPaySubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!newDesignerPay.designerId || !newDesignerPay.amount || !newDesignerPay.projectTitle) return;
      const amount = parseFloat(newDesignerPay.amount.replace(/,/g, ''));
      const designer = personnel.find(p => p.id === newDesignerPay.designerId);
      const record: DesignerPayment = {
          id: `dpay-${Date.now()}`,
          designerId: newDesignerPay.designerId,
          designerName: designer?.fullName || 'Unknown',
          projectTitle: newDesignerPay.projectTitle,
          amount: amount,
          currency: newDesignerPay.currency,
          date: newDesignerPay.date,
          isPaid: false,
          notes: newDesignerPay.notes,
          createdAt: new Date().toISOString(),
          recordedBy: currentUser.fullName
      };
      await saveDesignerPayment(record);
      alert(t.form.success);
      setNewDesignerPay({ ...newDesignerPay, amount: '', projectTitle: '', notes: '' });
