      e.preventDefault();
      if (!newSale.amount || !newSale.serviceId || !newSale.customerName) return;
      const amount = parseFloat(newSale.amount.replace(/,/g, ''));
      const rate = 10; // Simple logic for example
      const record: SalesRecord = {
          id: `sale-${Date.now()}`,
          salespersonId: newSale.salespersonId,
          salespersonName: personnel.find(p => p.id === newSale.salespersonId)?.fullName || 'Unknown',
          serviceId: newSale.serviceId,
          serviceTitle: services.find(s => s.id === newSale.serviceId)?.title || 'Service',
          customerName: newSale.customerName,
          saleAmount: amount,
          currency: newSale.currency,
          commissionRate: rate,
          commissionAmount: (amount * rate) / 100,
          commissionPaid: false,
          depositAccount: newSale.depositAccount,
          depositDate: newSale.depositDate,
          notes: newSale.notes,
          createdAt: new Date().toISOString()
      };
      await saveSalesRecord(record);
      alert(t.form.success);
      setNewSale({ ...newSale, amount: '', customerName: '', notes: '' });
      setActiveTab('my_sales');
  };

  // Fixed find name 'useMemo' error by adding it to imports
  const designerRankings = useMemo(() => {
      return designers.map(d => {
          const payments = designerPayments.filter(p => p.designerId === d.id);
          const totalEarned = payments.reduce((acc, p) => acc + p.amount, 0);
          return { ...d, totalEarned, projectCount: payments.length };
      }).sort((a, b) => b.totalEarned - a.totalEarned);
  }, [designers, designerPayments]);

  const displayDesignerPayments = designerPayments.filter(p => !selectedMonth || p.date.startsWith(selectedMonth));
  const filteredSales = salesRecords.filter(r => (activeTab === 'my_sales' ? r.salespersonId === currentUser.id : true) && (!selectedMonth || r.depositDate.startsWith(selectedMonth)));
  const displaySales = filteredSales.slice((currentPage - 1) * SALES_PER_PAGE, currentPage * SALES_PER_PAGE);

  return (
    <div className="space-y-6 animate-fade-in pb-20">
        <div className="flex flex-col lg:flex-row justify-between items-center bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-xl shadow-gray-200/50 gap-6">
            <div className="flex items-center gap-4">
                <div className="bg-indigo-600 text-white p-3 rounded-2xl shadow-lg shadow-indigo-100"><IconMoney className="w-6 h-6" /></div>
                <div><h2 className="text-xl font-black text-gray-900">{t.header}</h2><p className="text-sm text-gray-400 font-medium">{t.sub}</p></div>
            </div>
            <div className="flex bg-gray-100 p-1.5 rounded-2xl overflow-x-auto max-w-full no-scrollbar">
                <button onClick={() => setActiveTab('new_sale')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'new_sale' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.new}</button>
                <button onClick={() => setActiveTab('my_sales')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'my_sales' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.my}</button>
                {isMaster && (
                    <>
                        <button onClick={() => setActiveTab('all_sales')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'all_sales' ? 'bg-white shadow text-indigo-600' : 'text-gray-400'}`}>{t.tabs.all}</button>
                        <button onClick={() => setActiveTab('designers')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap flex items-center gap-2 ${activeTab === 'designers' ? 'bg-white shadow text-rose-600' : 'text-gray-400'}`}><IconPalette className="w-4 h-4" />{t.tabs.designers}</button>
                    </>
                )}
                <button onClick={() => setActiveTab('leaderboard')} className={`px-5 py-2.5 rounded-xl text-xs font-black transition-all whitespace-nowrap ${activeTab === 'leaderboard' ? 'bg-white shadow text-amber-600' : 'text-gray-400'}`}>{t.tabs.top}</button>
            </div>
        </div>

        {/* Filters Area */}
        {(activeTab === 'my_sales' || activeTab === 'all_sales' || activeTab === 'designers' || activeTab === 'leaderboard') && (
            <div className="flex bg-white p-4 rounded-3xl border border-gray-100 shadow-sm gap-4 items-center">
                <IconCalendar className="w-5 h-5 text-gray-400" />
                <input type="month" className="outline-none text-sm font-black text-gray-800" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)} />
                {selectedMonth && <button onClick={() => setSelectedMonth('')} className="text-red-400 hover:text-red-600"><IconRefreshCw className="w-4 h-4" /></button>}
            </div>
        )}

        {/* Tab Content: Designer Payments */}
        {activeTab === 'designers' && isMaster && (
            <div className="space-y-8 animate-fade-in">
                {/* Designer Leaderboard - Visualizing Collaboration */}
                <div className="bg-gradient-to-br from-rose-600 to-pink-700 p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                    <IconPalette className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10 rotate-12" />
                    <h3 className="text-2xl font-black mb-8 flex items-center gap-3"><IconTrophy className="w-6 h-6 text-amber-300" /> {t.designers.rankings}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {designerRankings.map((d, idx) => (
                            <div key={d.id} className="bg-white/10 backdrop-blur-md p-5 rounded-[2rem] border border-white/20 flex flex-col gap-4 relative group hover:bg-white/20 transition-all">
                                <div className="flex justify-between items-start">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center font-black">{idx + 1}</div>
                                        <div className="font-black">{d.fullName}</div>
                                    </div>
                                    <IconStar className={`w-5 h-5 ${idx === 0 ? 'text-amber-400 fill-current' : 'text-white/40'}`} />
                                </div>
                                <div className="space-y-1">
                                    <div className="text-[10px] uppercase font-black opacity-60 tracking-widest">{t.designers.totalEarned}</div>
                                    <div className="text-xl font-black">{d.totalEarned.toLocaleString()} <span className="text-[10px] font-medium opacity-50">IRR</span></div>
                                </div>
                                <div className="w-full bg-white/10 h-1.5 rounded-full overflow-hidden">
                                    <div className="bg-amber-400 h-full rounded-full shadow-[0_0_8px_rgba(251,191,36,0.5)] transition-all duration-1000" style={{ width: `${Math.min(100, (d.totalEarned / (designerRankings[0]?.totalEarned || 1)) * 100)}%` }}></div>
                                </div>
                                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-tighter opacity-60">
                                    <span>{d.projectCount} {t.designers.projectCount}</span>
                                    <span>{t.designers.collabPower}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Form and History */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* New Payment Form */}
                    <div className="lg:col-span-1 bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-xl">
                        <h3 className="text-lg font-black text-gray-900 mb-6 flex items-center gap-2"><IconPlus className="w-5 h-5 text-rose-500" /> {t.designers.new}</h3>
                        <form onSubmit={handleDesignerPaySubmit} className="space-y-5">
                            <div><label className="block text-[11px] font-black text-gray-400 mb-2 uppercase tracking-widest">{t.designers.select}</label>
                                <select required className="w-full px-5 py-3 rounded-2xl bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-rose-500 transition-all font-bold appearance-none" value={newDesignerPay.designerId} onChange={e => setNewDesignerPay({...newDesignerPay, designerId: e.target.value})}>
                                    <option value="">-</option>
                                    {designers.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                                </select>
                            </div>
                            <div><label className="block text-[11px] font-black text-gray-400 mb-2 uppercase tracking-widest">{t.designers.project}</label>
                                <input required className="w-full px-5 py-3 rounded-2xl bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-rose-500 transition-all font-bold" value={newDesignerPay.projectTitle} onChange={e => setNewDesignerPay({...newDesignerPay, projectTitle: e.target.value})} />
                            </div>
                            <div><label className="block text-[11px] font-black text-gray-400 mb-2 uppercase tracking-widest">{t.designers.amount}</label>
                                <div className="flex gap-2">
                                    <input required className="flex-grow px-5 py-3 rounded-2xl bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-rose-500 transition-all font-mono font-black dir-ltr text-right" value={newDesignerPay.amount} onChange={e => setNewDesignerPay({...newDesignerPay, amount: handleAmountInput(e.target.value)})} placeholder="0" />
                                    <select className="w-20 px-2 rounded-2xl bg-gray-50 font-black text-xs" value={newDesignerPay.currency} onChange={e => setNewDesignerPay({...newDesignerPay, currency: e.target.value as any})}><option value="IRR">IRR</option><option value="USD">USD</option></select>
                                </div>
                            </div>
                            <button type="submit" className="w-full py-4 bg-rose-600 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-rose-100 hover:bg-rose-700 transition-all active:scale-95">{t.form.submit}</button>
                        </form>
                    </div>

                    {/* Payment History List */}
                    <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-gray-100 shadow-xl overflow-hidden flex flex-col">
                        <div className="p-6 bg-gray-50/50 border-b border-gray-100 font-black text-gray-700 text-sm uppercase tracking-wider">{t.tabs.designers} (سابقه)</div>
                        <div className="flex-grow overflow-y-auto max-h-[600px] custom-scrollbar">
                            <table className="w-full text-start">
                                <thead className="bg-gray-50 text-[10px] text-gray-400 font-black uppercase tracking-widest">
                                    <tr>
                                        <th className="px-6 py-4 text-start">{t.table.seller}</th>
                                        <th className="px-6 py-4 text-start">{t.designers.project}</th>
                                        <th className="px-6 py-4 text-center">{t.table.amount}</th>
                                        <th className="px-6 py-4 text-center">{t.table.status}</th>
                                        <th className="px-6 py-4 text-center">...</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50">
                                    {displayDesignerPayments.map(p => (
                                        <tr key={p.id} className="hover:bg-rose-50/20 transition-colors group">
                                            <td className="px-6 py-4">
                                                <div className="font-black text-gray-800 text-sm">{p.designerName}</div>
                                                <div className="text-[10px] text-gray-400">{p.date}</div>
                                            </td>
                                            <td className="px-6 py-4 text-sm font-bold text-gray-600">{p.projectTitle}</td>
                                            <td className="px-6 py-4 text-center">
                                                <span className="font-black text-rose-600">{p.amount.toLocaleString()}</span>
                                                <span className="text-[9px] text-gray-400 ml-1">{p.currency}</span>
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                <button onClick={() => updateDesignerPayment(p.id, { isPaid: !p.isPaid }, currentUser.fullName)} className={`px-3 py-1 rounded-full text-[9px] font-black transition-all ${p.isPaid ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{p.isPaid ? t.table.paid : t.table.pending}</button>
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                <button onClick={() => deleteDesignerPayment(p.id, currentUser.fullName)} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><IconTrash className="w-4 h-4" /></button>
                                            </td>
                                        </tr>
                                    ))}
                                    {displayDesignerPayments.length === 0 && <tr><td colSpan={5} className="py-20 text-center text-gray-400 font-bold italic">{t.table.empty}</td></tr>}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Tab Content: New Sale */}
        {activeTab === 'new_sale' && (
            <div className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-2xl max-w-4xl mx-auto animate-fade-in">
                <h3 className="text-2xl font-black text-gray-900 mb-8 flex items-center gap-3"><IconPlus className="w-6 h-6 text-green-500" /> {t.tabs.new}</h3>
                <form onSubmit={handleSaleSubmit} className="space-y-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div><label className="block text-[11px] font-black text-gray-400 mb-3 uppercase tracking-widest">{t.form.salesperson}</label>
                            <select className="w-full px-6 py-4 rounded-[1.5rem] bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-green-500 transition-all font-bold appearance-none" value={newSale.salespersonId} onChange={e => setNewSale({...newSale, salespersonId: e.target.value})} disabled={!isMaster}>
                                {salesPersonnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                            </select>
                        </div>
                        <div><label className="block text-[11px] font-black text-gray-400 mb-3 uppercase tracking-widest">{t.form.service}</label>
                            <select className="w-full px-6 py-4 rounded-[1.5rem] bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-green-500 transition-all font-bold appearance-none" value={newSale.serviceId} onChange={e => setNewSale({...newSale, serviceId: e.target.value})} required>
                                <option value="">-</option>
                                {services.filter(s => s.isActive).map(s => <option key={s.id} value={s.id}>{s.title}</option>)}
                            </select>
                        </div>
                        <div><label className="block text-[11px] font-black text-gray-400 mb-3 uppercase tracking-widest">{t.form.customer}</label>
                            <input className="w-full px-6 py-4 rounded-[1.5rem] bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-green-500 transition-all font-bold" value={newSale.customerName} onChange={e => setNewSale({...newSale, customerName: e.target.value})} required />
                        </div>
                        <div><label className="block text-[11px] font-black text-gray-400 mb-3 uppercase tracking-widest">{t.form.amount}</label>
                            <div className="flex gap-2">
                                <input className="flex-grow px-6 py-4 rounded-[1.5rem] bg-gray-50 border border-transparent outline-none focus:bg-white focus:border-green-500 transition-all font-mono font-black dir-ltr text-right" value={newSale.amount} onChange={e => setNewSale({...newSale, amount: handleAmountInput(e.target.value)})} placeholder="0" required />
                                <select className="w-24 px-2 rounded-[1.5rem] bg-gray-50 font-black text-xs" value={newSale.currency} onChange={e => setNewSale({...newSale, currency: e.target.value as Currency})}><option value="IRR">IRR</option><option value="USD">USD</option></select>
                            </div>
                        </div>
                    </div>
                    <button type="submit" className="w-full py-5 bg-green-600 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl shadow-green-100 hover:bg-green-700 transition-all active:scale-95 flex items-center justify-center gap-3"><IconCheck className="w-6 h-6" /> {t.form.submit}</button>
                </form>
            </div>
        )}

        {/* Sales Table with Row Numbers & Pagination */}
        {(activeTab === 'my_sales' || activeTab === 'all_sales') && (
            <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-2xl overflow-hidden animate-fade-in">
                <div className="overflow-x-auto">
                    <table className="w-full text-start">
                        <thead className="bg-gray-50/80 text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] border-b border-gray-100">
                            <tr>
                                <th className="px-6 py-5 text-center w-12">{t.table.row}</th>
                                <th className="px-6 py-5 text-start">{t.table.seller}</th>
                                <th className="px-6 py-5 text-start">{t.table.customer}</th>
                                <th className="px-6 py-5 text-start">{t.table.service}</th>
                                <th className="px-6 py-5 text-center">{t.table.amount}</th>
                                <th className="px-6 py-5 text-center">{t.table.commission}</th>
                                <th className="px-6 py-5 text-center">{t.table.status}</th>
                                <th className="px-6 py-5 text-center w-20">...</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {displaySales.map((sale, index) => (
                                <tr key={sale.id} className={`transition-all hover:bg-indigo-50/30 group ${sale.commissionPaid ? 'opacity-60 grayscale' : ''}`}>
                                    <td className="px-6 py-5 text-center text-[10px] font-black text-gray-400">{(currentPage - 1) * SALES_PER_PAGE + index + 1}</td>
                                    <td className="px-6 py-5 font-black text-gray-900 text-sm">{sale.salespersonName}</td>
                                    <td className="px-6 py-5 text-sm font-bold text-gray-500">{sale.customerName}</td>
                                    <td className="px-6 py-5 text-sm font-bold text-indigo-600">{sale.serviceTitle}</td>
                                    <td className="px-6 py-5 text-center font-black text-gray-800">{sale.saleAmount.toLocaleString()} <span className="text-[9px] font-medium opacity-40">{sale.currency}</span></td>
                                    <td className="px-6 py-5 text-center">
                                        <div className="inline-flex flex-col items-center">
                                            <span className="font-black text-green-600">{sale.commissionAmount.toLocaleString()}</span>
                                            <span className="text-[9px] font-bold text-gray-400">({sale.commissionRate}%)</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-5 text-center">
                                        <button onClick={() => isMaster && updateSalesRecord(sale.id, { commissionPaid: !sale.commissionPaid }, currentUser.fullName)} className={`px-4 py-1.5 rounded-full text-[10px] font-black transition-all ${sale.commissionPaid ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700 hover:bg-amber-200'}`}>{sale.commissionPaid ? t.table.paid : t.table.pending}</button>
                                    </td>
                                    <td className="px-6 py-5 text-center">
                                        <div className="flex gap-2 justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            {isMaster && (
                                                <>
                                                    <button onClick={() => setEditingSale(sale)} className="text-indigo-400 hover:text-indigo-600"><IconEdit className="w-4 h-4" /></button>
                                                    <button onClick={() => deleteSalesRecord(sale.id, currentUser.fullName)} className="text-gray-300 hover:text-red-500"><IconTrash className="w-4 h-4" /></button>
                                                </>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        )}

        {/* Leaderboard View */}
        {activeTab === 'leaderboard' && (
            <div className="bg-white p-10 rounded-[3rem] border border-gray-100 shadow-2xl animate-fade-in relative overflow-hidden">
                <IconTrophy className="absolute -left-10 -bottom-10 w-64 h-64 opacity-5 rotate-12" />
                <h3 className="text-2xl font-black text-gray-900 mb-10 text-center">{t.tabs.top}</h3>
                <div className="max-w-3xl mx-auto space-y-4">
                    {salesPersonnel.map((person, idx) => {
                        const personSales = salesRecords.filter(r => r.salespersonId === person.id && (!selectedMonth || r.depositDate.startsWith(selectedMonth)));
                        const grossSales = personSales.reduce((acc, r) => acc + r.saleAmount, 0);
                        const netProfit = personSales.reduce((acc, r) => acc + (r.saleAmount - r.commissionAmount), 0);
                        return { ...person, grossSales, netProfit };
                    }).sort((a, b) => b.netProfit - a.netProfit).map((p, idx) => (
                        <div key={p.id} className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all ${idx === 0 ? 'bg-amber-50 border-amber-200 scale-105 shadow-xl shadow-amber-100' : 'bg-gray-50/50 border-gray-100'}`}>
                            <div className="flex items-center gap-6">
                                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-xl ${idx === 0 ? 'bg-amber-400 text-white' : 'bg-indigo-100 text-indigo-600'}`}>{idx + 1}</div>
                                <div><div className="font-black text-lg text-gray-900">{p.fullName}</div><div className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.roles[0]}</div></div>
                            </div>
                            <div className="text-right">
                                <div className="text-xl font-black text-indigo-900">{p.netProfit.toLocaleString()} <span className="text-[10px] opacity-40">IRR</span></div>
                                <div className="text-[10px] font-bold text-gray-400 uppercase mt-1">سود خالص برای شرکت</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}
    </div>
  );
};
